/**
 * Build THE PATCH SKIFF from "Mech Drone" by Willy Decarpentrie
 * (Sketchfab, CC BY 4.0) — Tirtha's pick from /skiffs.html, repainted
 * in Expanse colours (burnt-orange accents, Belter-teal lens, grimed
 * steel; the repaint lives in the baseColor texture, generated by the
 * session's PIL pass).
 *
 *   node scripts/build-mechskiff.mjs <src converted.glb> <paint.png> <out.glb>
 *
 * UNLIKE the hull pipeline this keeps the SKIN and the animation
 * ("Take 001" — the arms work) — so no bake, no weld, no simplify, no
 * quantize. Texture swap + webp + meshopt reorder only.
 */
import { NodeIO } from '@gltf-transform/core'
import { ALL_EXTENSIONS, EXTMeshoptCompression } from '@gltf-transform/extensions'
import { prune, dedup, textureCompress, reorder } from '@gltf-transform/functions'
import { MeshoptEncoder, MeshoptDecoder } from 'meshoptimizer'
import sharp from 'sharp'
import { readFileSync, statSync } from 'node:fs'

const [, , SRC, PAINT, OUT] = process.argv
await MeshoptEncoder.ready
await MeshoptDecoder.ready
const io = new NodeIO()
  .registerExtensions(ALL_EXTENSIONS)
  .registerDependencies({ 'meshopt.encoder': MeshoptEncoder, 'meshopt.decoder': MeshoptDecoder })
const doc = await io.read(SRC)

for (const m of doc.getRoot().listMaterials()) {
  if (m.getName() === 'Robot') {
    const t = m.getBaseColorTexture()
    t.setImage(readFileSync(PAINT)).setMimeType('image/png')
    m.setMetallicFactor(0.8)
    m.setRoughnessFactor(1.0)
  }
}

await doc.transform(
  prune(),
  dedup(),
  textureCompress({ encoder: sharp, targetFormat: 'webp', resize: [1024, 1024] }),
  reorder({ encoder: MeshoptEncoder }),
)
doc.createExtension(EXTMeshoptCompression).setRequired(true).setEncoderOptions({
  method: EXTMeshoptCompression.EncoderMethod.FILTER,
})
await io.write(OUT, doc)
console.log(`wrote ${OUT}: ${statSync(OUT).size} bytes`)
